"""#*Visualize Raw Data*"""

import matplotlib.pyplot as plt
import numpy as np

# Define colors for each suffix
color_map = {'2': 'blue', '5': 'green', '8': 'red', '10': 'purple'}
#, '20': 'yellow', '30': 'orange', '40': 'cyan', '100': 'black'

# Plotting Lipids
plt.figure(figsize=(10, 6))
# Plot baseline
for col in spiru_data.columns:
  if col.startswith('Baseline_'):
    plt.plot(spiru_data['Wavlen'], spiru_data[col], color='black', linestyle='-', alpha=0.5, label='Baseline' if 'Baseline' not in plt.gca().get_legend_handles_labels()[1] else "")
# Plot Lipid spectra with color mapping based on suffix
for col in spiru_data.columns:
  if col.startswith('Lipid'):
    suffix = col.split('_')[0].replace('Lipid', '')
    if suffix in color_map:
      plt.plot(spiru_data['Wavlen'], spiru_data[col], color=color_map[suffix], linestyle='-', alpha=0.7, label=f'Lipid {suffix}%' if f'Lipid {suffix}%' not in plt.gca().get_legend_handles_labels()[1] else "")
plt.xlabel('Wavelength (nm)', fontsize = 24, family='Sans serif')
plt.ylabel('Reflectance', fontsize = 24, family='Sans serif')
#plt.title('Lipid Spectra')
plt.legend(fontsize = 16)
plt.grid(True)
plt.show()

