import pandas as pd
import numpy as np
from scipy.signal import savgol_filter
import matplotlib.pyplot as plt

def SG1(X):
  window_length = 11
  polyorder = 2
  deriv = 1
  return savgol_filter(X, window_length, polyorder, deriv)

