# Plotting function
def plot_spectra(ax, data, analyte, y_label, title):
    for col in data.columns:
        if col.startswith('Baseline_'):
            ax.plot(data['Wavlen'], data[col], color='black', linestyle='-', alpha=0.5,
                    label='Baseline' if 'Baseline' not in ax.get_legend_handles_labels()[1] else "")
        elif col.startswith(analyte):
            suffix = col.split('_')[0].replace(analyte, '')
            if suffix in color_map:
                label_name = f'{analyte} {suffix}%' if f'{analyte} {suffix}%' not in ax.get_legend_handles_labels()[1] else ""
                ax.plot(data['Wavlen'], data[col], color=color_map[suffix], linestyle='-', alpha=0.7, label=label_name)
    ax.set_title(f"{title} - {analyte}s")
    ax.set_xlabel("Wavlen (nm)")
    ax.set_ylabel(y_label)
    ax.legend()
    ax.grid(True)

# Loop over datasets and analytes
for j, (title, data, ylabel) in enumerate(datasets):
    for i, analyte in enumerate(analytes):
        plot_spectra(axes[i, j], data, analyte, ylabel, title)

plt.tight_layout()
plt.show()

