group_indices = {percentage: group_df.index.tolist() for percentage, group_df in grouped_data}

fold = 1

X_train_list = []
X_test_list = []
y_train_list = []
y_test_list = []

for percentage, indices in group_indices.items():

    test_indices_group = indices[0:3]
    train_indices_group = indices[3:15]

    X_train_list.append(X.loc[train_indices_group])
    X_test_list.append(X.loc[test_indices_group])
    y_train_list.append(y.loc[train_indices_group])
    y_test_list.append(y.loc[test_indices_group])

    X_cv_train = pd.concat(X_train_list)
    X_cv_test = pd.concat(X_test_list)
    y_cv_train = pd.concat(y_train_list)
    y_cv_test = pd.concat(y_test_list)


results = []
for n_components in range(1, 15):
    print(f"Using {n_components} components for PLSR (Fold {fold}).")

    pls_model = PLSRegression(n_components=n_components)
    pls_model.fit(X_cv_train, y_cv_train)
    y_cv_pred = pls_model.predict(X_cv_test)

    mse_cv = mean_squared_error(y_cv_test, y_cv_pred)
    rmse_cv = np.sqrt(mse_cv)
    r2_cv = r2_score(y_cv_test, y_cv_pred)
    nse_cv = nash_sutcliffe_efficiency(y_cv_test, y_cv_pred)
    rss = np.sum((y_cv_test - y_cv_pred)**2)
    aic_cv = calculate_aic(n_components, len(y_cv_test), rss)

    results.append({'n_components': n_components, 'MSE': mse_cv, 'RMSE': rmse_cv, 'R2': r2_cv, 'NSE': nse_cv, 'AIC': aic_cv})

# Display results
results_df = pd.DataFrame(results)
