y = pd.Series(y_labels, index=X.index) # Ensure y has the same index as X


grouped_data = pd.concat([X, y.rename('Protein_Percentage')], axis=1).groupby('Protein_Percentage')
group_indices = {percentage: group_df.index.tolist() for percentage, group_df in grouped_data}

cv_results = []

n_folds = 5
n_components = 6

for fold in range(1, n_folds + 1):
    X_train_list = []
    X_test_list = []
    y_train_list = []
    y_test_list = []

    for percentage, indices in group_indices.items():
        # Use group indices split for current fold
        if fold == 1:
            test_indices_group = indices[0:3]
            train_indices_group = indices[3:15]
        elif fold == 2:
            test_indices_group = indices[3:6]
            train_indices_group = indices[0:3] + indices[6:15]
        elif fold == 3:
            test_indices_group = indices[6:9]
            train_indices_group = indices[0:6] + indices[9:15]
        elif fold == 4:
            test_indices_group = indices[9:12]
            train_indices_group = indices[0:9] + indices[12:15]
        elif fold == 5:
            test_indices_group = indices[12:15]
            train_indices_group = indices[0:12]

        X_train_list.append(X.loc[train_indices_group])
        X_test_list.append(X.loc[test_indices_group])
        y_train_list.append(y.loc[train_indices_group])
        y_test_list.append(y.loc[test_indices_group])

    # Concatenate all groups together for this fold
    X_cv_train = pd.concat(X_train_list)
    X_cv_test = pd.concat(X_test_list)
    y_cv_train = pd.concat(y_train_list)
    y_cv_test = pd.concat(y_test_list)

    print(f"Using {n_components} components for PLSR (Fold {fold}).")

    pls_model = PLSRegression(n_components=n_components)
    pls_model.fit(X_cv_train, y_cv_train)
    y_cv_pred_train = pls_model.predict(X_cv_train)
    y_cv_pred_test = pls_model.predict(X_cv_test)

    mse_cv_train = mean_squared_error(y_cv_train, y_cv_pred_train)
    rmse_cv_train = np.sqrt(mse_cv_train)
    r2_cv_train = r2_score(y_cv_train, y_cv_pred_train)

    mse_cv_test = mean_squared_error(y_cv_test, y_cv_pred_test)
    rmse_cv_test = np.sqrt(mse_cv_test)
    r2_cv_test = r2_score(y_cv_test, y_cv_pred_test)
    rpd_cv_test = np.std(y_cv_test, ddof=1) / rmse_cv_test

    cv_results.append({'Fold': fold, 'Train RMSE': rmse_cv_train, 'Train R2': r2_cv_train, 'Test RMSE': rmse_cv_test, 'Test R2': r2_cv_test, 'Test RPD': rpd_cv_test})

    # Plot fold results
    plt.figure(figsize=(8, 6))
    plt.scatter(y_cv_train, y_cv_pred_train)
    plt.scatter(y_cv_test, y_cv_pred_test)
    plt.xlabel("Actual Protein Percentage")
    plt.ylabel("Predicted Protein Percentage")
    #plt.title(f"Cross-Validation Fold {fold}: Actual vs Predicted Protein Percentage")
    plt.grid(True)
    plt.plot([y.min(), y.max()], [y.min(), y.max()], 'k--', lw=2)
    plt.text(0.05, 0.95, f'Fold: {fold}\nTrain RMSE: {rmse_cv_train:.2f}\nTrain R^2: {r2_cv_train:.2f}\nTest RMSE: {rmse_cv_test:.2f}\nTest R^2: {r2_cv_test:.2f}\nRPD: {rpd_cv_test:.2f}', transform=plt.gca().transAxes, fontsize=10, verticalalignment='top')
