# Plot NSE
axes[1, 0].plot(results_df['n_components'], results_df['NSE'], marker='o', color='green')
axes[1, 0].set_xlabel('Number of Components')
axes[1, 0].set_ylabel('Nash-Sutcliffe Efficiency (NSE)')
