from sklearn.cross_decomposition import PLSRegression
from sklearn.model_selection import train_test_split, KFold
from sklearn.metrics import mean_squared_error, r2_score
import numpy as np
import matplotlib.pyplot as plt
import pandas as pd


# Function to calculate Nash-Sutcliffe Efficiency (NSE)
def nash_sutcliffe_efficiency(y_true, y_pred):
    numerator = np.sum((y_true - y_pred)**2)
    denominator = np.sum((y_true - np.mean(y_true))**2)
    return 1 - (numerator / denominator)

# Function to calculate Akaike Information Criterion (AIC)
# For PLSR, a common approach is to use the residual sum of squares
def calculate_aic(n_components, n_samples, rss):
    k = n_components # Number of parameters
    return n_samples * np.log(rss / n_samples) - 2 * k


# Identify columns for protein and baseline in the transformed data
protein_cols = [col for col in transform_SG_chlorella_data.columns if col.startswith('Protein')]
baseline_cols = [col for col in transform_SG_chlorella_data.columns if col.startswith('Baseline')]

# Combine protein and baseline columns
# Transpose the data - rows are samples and columns are wavelengths
X = transform_SG_chlorella_data[baseline_cols + protein_cols].T

# Create corresponding labels (protein percentages) for the samples in X
protein_percentages_map = {
    'Protein2': 54.04,
    'Protein5': 55.45,
    'Protein8': 56.85,
    'Protein10': 57.79
}

y_labels = []
for col in baseline_cols + protein_cols:
  if col.startswith('Baseline'):
    y_labels.append(53.10)
  elif col.startswith('Protein'):
      protein_type = col.split('_')[0].replace('Protein','')
      if protein_type.isdigit():
        y_labels.append(protein_percentages_map[f'Protein{protein_type}'])

y = pd.Series(y_labels, index=X.index) # Ensure y has the same index as X


# Group data by protein percentage for controlled splitting
grouped_data = pd.concat([X, y.rename('Protein_Percentage')], axis=1).groupby('Protein_Percentage')
group_indices = {percentage: group_df.index.tolist() for percentage, group_df in grouped_data}

fold = 1

X_train_list = []
X_test_list = []
y_train_list = []
y_test_list = []

for percentage, indices in group_indices.items():

    test_indices_group = indices[0:3]
    train_indices_group = indices[3:15]

    X_train_list.append(X.loc[train_indices_group])
    X_test_list.append(X.loc[test_indices_group])
    y_train_list.append(y.loc[train_indices_group])
    y_test_list.append(y.loc[test_indices_group])

    X_cv_train = pd.concat(X_train_list)
    X_cv_test = pd.concat(X_test_list)
    y_cv_train = pd.concat(y_train_list)
    y_cv_test = pd.concat(y_test_list)


results = []
for n_components in range(1, 10):
    print(f"Using {n_components} components for PLSR (Fold {fold}).")

    pls_model = PLSRegression(n_components=n_components)
    pls_model.fit(X_cv_train, y_cv_train)
    y_cv_pred = pls_model.predict(X_cv_test)

    mse_cv = mean_squared_error(y_cv_test, y_cv_pred)
    rmse_cv = np.sqrt(mse_cv)
    r2_cv = r2_score(y_cv_test, y_cv_pred)
    nse_cv = nash_sutcliffe_efficiency(y_cv_test, y_cv_pred)
    rss = np.sum((y_cv_test - y_cv_pred)**2)
    aic_cv = calculate_aic(n_components, len(y_cv_test), rss)

    results.append({'n_components': n_components, 'MSE': mse_cv, 'RMSE': rmse_cv, 'R2': r2_cv, 'NSE': nse_cv, 'AIC': aic_cv})

# Display results
results_df = pd.DataFrame(results)
display(results_df)


# Plotting metrics in a 2x2 grid
