std_r2_test = cv_results_df['Test R2'].std()
mean_rpd_test = cv_results_df['Test RPD'].mean()
std_rpd_test = cv_results_df['Test RPD'].std()

print(f"Mean Train RMSE across folds: {mean_rmse_train:.2f}")
print(f"Standard Deviation Train RMSE across folds: {std_rmse_train:.2f}")
print(f"Mean Train R2 across folds: {mean_r2_train:.2f}")
