from sklearn.decomposition import PCA
from sklearn.linear_model import LinearRegression
from sklearn.model_selection import train_test_split, KFold
from sklearn.metrics import mean_squared_error, r2_score
import numpy as np
import matplotlib.pyplot as plt
import pandas as pd

# Identify columns for carb and baseline in the transformed data
carb_cols = [col for col in transform_MSC_spiru_data.columns if col.startswith('Carb')]
baseline_cols = [col for col in transform_MSC_spiru_data.columns if col.startswith('Baseline')]

# Combine carb and baseline columns
# Transpose the data - rows are samples and columns are wavelengths
X = transform_MSC_spiru_data[baseline_cols + carb_cols].T

# Create corresponding labels (carb percentages) for the samples in X
carb_percentages_map = {
    'Carb2': 29.07,
    'Carb5': 31.24,
    'Carb8': 33.41,
    'Carb10': 34.86
}

y_labels = []
for col in baseline_cols + carb_cols:
  if col.startswith('Baseline'):
    y_labels.append(27.62)
  elif col.startswith('Carb'):
      carb_type = col.split('_')[0].replace('Carb','')
      if carb_type.isdigit():
        y_labels.append(carb_percentages_map[f'Carb{carb_type}'])

y = pd.Series(y_labels, index=X.index) # Ensure y has the same index as X


grouped_data = pd.concat([X, y.rename('Carb_Percentage')], axis=1).groupby('Carb_Percentage')
group_indices = {percentage: group_df.index.tolist() for percentage, group_df in grouped_data}

cv_results = []

n_folds = 5

for fold in range(1, n_folds + 1):
    X_train_list = []
    X_test_list = []
    y_train_list = []
    y_test_list = []

    for percentage, indices in group_indices.items():
        # Use group indices split for current fold
        if fold == 1:
            test_indices_group = indices[0:3]
            train_indices_group = indices[3:15]
        elif fold == 2:
            test_indices_group = indices[3:6]
            train_indices_group = indices[0:3] + indices[6:15]
        elif fold == 3:
            test_indices_group = indices[6:9]
            train_indices_group = indices[0:6] + indices[9:15]
        elif fold == 4:
            test_indices_group = indices[9:12]
            train_indices_group = indices[0:9] + indices[12:15]
        elif fold == 5:
            test_indices_group = indices[12:15]
            train_indices_group = indices[0:12]

        X_train_list.append(X.loc[train_indices_group])
        X_test_list.append(X.loc[test_indices_group])
        y_train_list.append(y.loc[train_indices_group])
        y_test_list.append(y.loc[test_indices_group])

    # Concatenate all groups together for this fold
    X_cv_train = pd.concat(X_train_list)
    X_cv_test = pd.concat(X_test_list)
    y_cv_train = pd.concat(y_train_list)
    y_cv_test = pd.concat(y_test_list)

    pca_model = PCA(n_components=0.90)
    pca_model.fit(X_cv_train)

    X_cv_train = pca_model.transform(X_cv_train)
    X_cv_test = pca_model.transform(X_cv_test)

    pcr_model = LinearRegression()
    pcr_model.fit(X_cv_train, y_cv_train)
    y_cv_pred_train = pcr_model.predict(X_cv_train)
    y_cv_pred_test = pcr_model.predict(X_cv_test)

    mse_cv_train = mean_squared_error(y_cv_train, y_cv_pred_train)
    rmse_cv_train = np.sqrt(mse_cv_train)
