    plt.scatter(y_cv_train, y_cv_pred_train)
    plt.scatter(y_cv_test, y_cv_pred_test)
    plt.xlabel("Actual Protein Percentage")
    plt.ylabel("Predicted Protein Percentage")
    #plt.title(f"Cross-Validation Fold {fold}: Actual vs Predicted Protein Percentage")
    plt.grid(True)
    plt.plot([y.min(), y.max()], [y.min(), y.max()], 'k--', lw=2)
    plt.text(0.05, 0.95, f'Fold: {fold}\nTrain RMSE: {rmse_cv_train:.2f}\nTrain R^2: {r2_cv_train:.2f}\nTest RMSE: {rmse_cv_test:.2f}\nTest R^2: {r2_cv_test:.2f}\nRPD: {rpd_cv_test:.2f}', transform=plt.gca().transAxes, fontsize=10, verticalalignment='top')
    plt.show()

