from sklearn.ensemble import RandomForestRegressor
from sklearn.model_selection import GridSearchCV
from sklearn.preprocessing import StandardScaler
from sklearn.metrics import mean_squared_error, r2_score
import numpy as np
import matplotlib.pyplot as plt
import pandas as pd
import os

lipid_cols = [col for col in transform_SG1_spiru_data.columns if col.startswith('Lipid')]
baseline_cols = [col for col in transform_SG1_spiru_data.columns if col.startswith('Baseline')]

X = transform_SG1_spiru_data[baseline_cols + lipid_cols].T

lipid_percentages_map = {
    'Lipid2': 2.62,
    'Lipid5': 5.60,
    'Lipid8': 8.58,
    'Lipid10': 10.57
}

y_labels = []
for col in baseline_cols + lipid_cols:
    if col.startswith('Baseline'):
        y_labels.append(0.63)
    else:
        lipid_type = col.split('_')[0].replace('Lipid', '')
        y_labels.append(lipid_percentages_map[f"Lipid{lipid_type}"])

y = pd.Series(y_labels, index=X.index)

grouped_data = pd.concat([X, y.rename('Lipid_Percentage')], axis=1).groupby('Lipid_Percentage')
group_indices = {pct: df.index.tolist() for pct, df in grouped_data}

cv_results = []
n_folds = 5
output_dir = "./rf_results"
os.makedirs(output_dir, exist_ok=True)

param_grid = {
    'n_estimators': [50, 100, 200],
    'max_depth': [None, 5, 10, 20],
    'min_samples_split': [2, 5, 10],
}

for fold in range(1, n_folds + 1):

    X_train_list, X_test_list = [], []
    y_train_list, y_test_list = [], []

    # Manual group-based splitting
    for pct, indices in group_indices.items():
        if fold == 1:
            test_i = indices[0:3]
            train_i = indices[3:15]
        elif fold == 2:
            test_i = indices[3:6]
            train_i = indices[0:3] + indices[6:15]
        elif fold == 3:
            test_i = indices[6:9]
            train_i = indices[0:6] + indices[9:15]
        elif fold == 4:
            test_i = indices[9:12]
            train_i = indices[0:9] + indices[12:15]
        elif fold == 5:
            test_i = indices[12:15]
            train_i = indices[0:12]

        X_train_list.append(X.loc[train_i])
        X_test_list.append(X.loc[test_i])
        y_train_list.append(y.loc[train_i])
        y_test_list.append(y.loc[test_i])

    # Merge groups
    X_train = pd.concat(X_train_list)
    X_test = pd.concat(X_test_list)
    y_train = pd.concat(y_train_list)
    y_test = pd.concat(y_test_list)

    scaler = StandardScaler()
    X_train_scaled = scaler.fit_transform(X_train)
    X_test_scaled = scaler.transform(X_test)

    rf_model = RandomForestRegressor(random_state=42)

    grid_search = GridSearchCV(
        rf_model, param_grid,
        cv=5,
        scoring='neg_root_mean_squared_error',
        n_jobs=-1
    )
    grid_search.fit(X_train_scaled, y_train)

    print(f"\n===== Fold {fold} =====")
    print("Best RF parameters:", grid_search.best_params_)

    # Save best params
    with open(os.path.join(output_dir, f"best_rf_params_fold{fold}.txt"), "w") as f:
        f.write(str(grid_search.best_params_))

    # Best model
    rf = grid_search.best_estimator_
    y_pred_train = rf.predict(X_train_scaled)
    y_pred_test = rf.predict(X_test_scaled)

    rmse_train = np.sqrt(mean_squared_error(y_train, y_pred_train))
    r2_train = r2_score(y_train, y_pred_train)

    rmse_test = np.sqrt(mean_squared_error(y_test, y_pred_test))
    r2_test = r2_score(y_test, y_pred_test)
    rpd_test = np.std(y_test, ddof=1) / rmse_test

    cv_results.append({
        'Fold': fold,
        'Train RMSE': rmse_train,
        'Train R2': r2_train,
        'Test RMSE': rmse_test,
        'Test R2': r2_test,
        'Test RPD': rpd_test
    })

    plt.figure(figsize=(8, 6))
    plt.scatter(y_train, y_pred_train, label="Train")
    plt.scatter(y_test, y_pred_test, label="Test")
    plt.plot([y.min(), y.max()], [y.min(), y.max()], "k--")

    plt.xlabel("Actual Lipid Percentage")
    plt.ylabel("Predicted Lipid Percentage")
    #plt.title(f"Random Forest - Fold {fold}")
    plt.grid(True)

    plt.text(0.05, 0.95, f"Fold: {fold}\n"
             f"Train RMSE: {rmse_train:.2f}\nTrain R2: {r2_train:.2f}\n"
             f"Test RMSE: {rmse_test:.2f}\nTest R2: {r2_test:.2f}\nRPD: {rpd_test:.2f}",
             transform=plt.gca().transAxes, va="top")
    plt.legend()
    plt.show()

cv_df = pd.DataFrame(cv_results)
print("\nCross-Validation Results:")
display(cv_df)

print("\n===== Overall Averages =====")
print(cv_df.mean(numeric_only=True))
print("\n===== Standard Deviations =====")
print(cv_df.std(numeric_only=True))

